const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const toks = lines.join(' ').split(/\s+/).filter(x => x.length);
const h = Number(toks[0]), w = Number(toks[1]);
const g = toks.slice(2, 2 + h);
const MOD = 1000000007;
const dp = Array.from({ length: h }, () => new Array(w).fill(0));
if (g[0][0] === '.') dp[0][0] = 1;
for (let i = 0; i < h; i++) {
  for (let j = 0; j < w; j++) {
    if (g[i][j] === '#') { dp[i][j] = 0; continue; }
    if (i === 0 && j === 0) continue;
    const up = i ? dp[i - 1][j] : 0, left = j ? dp[i][j - 1] : 0;
    dp[i][j] = (up + left) % MOD;
  }
}
console.log(dp[h - 1][w - 1]);

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt(), w = sc.nextInt();
        String[] g = new String[h];
        for (int i = 0; i < h; i++) g[i] = sc.next();
        final int MOD = 1_000_000_007;
        int[][] dp = new int[h][w];
        if (g[0].charAt(0) == '.') dp[0][0] = 1;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (g[i].charAt(j) == '#') { dp[i][j] = 0; continue; }
                if (i == 0 && j == 0) continue;
                long up = i > 0 ? dp[i - 1][j] : 0, left = j > 0 ? dp[i][j - 1] : 0;
                dp[i][j] = (int) ((up + left) % MOD);
            }
        }
        System.out.println(dp[h - 1][w - 1]);
    }
}

