#include <bits/stdc++.h>
using namespace std;
int main() {
    int h, w;
    cin >> h >> w;
    vector<string> g(h);
    for (auto& row : g) cin >> row;
    const int MOD = 1000000007;
    vector<vector<int>> dp(h, vector<int>(w, 0));
    if (g[0][0] == '.') dp[0][0] = 1;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (g[i][j] == '#') { dp[i][j] = 0; continue; }
            if (i == 0 && j == 0) continue;
            long long up = i ? dp[i - 1][j] : 0, left = j ? dp[i][j - 1] : 0;
            dp[i][j] = (up + left) % MOD;
        }
    }
    printf("%d\n", dp[h - 1][w - 1]);
    return 0;
}
